assert len(_RAINY_RECORDS) == 1000 * 14 * 8


def rainy_identity(clean_id: int, rain_id: int) -> tuple[int, int]:
    if not 1 <= clean_id <= 1000 or not 1 <= rain_id <= 14:
        raise ValueError("Unknown official Rain1400 source/rain ID")
    return struct.unpack_from("<II", _RAINY_RECORDS, ((clean_id - 1) * 14 + rain_id - 1) * 8)
